    float3 rgb2yuv(float3 c) {
        float y =  0.2126*c.r + 0.7152*c.g + 0.0722*c.b;
        float u = -0.1146*c.r - 0.3854*c.g + 0.5000*c.b;
        float v =  0.5000*c.r - 0.4542*c.g - 0.0458*c.b;
        return float3(y, u, v);
    }
    float3 yuv2rgb(float3 yuv) {
        float r = yuv.x                + 1.5748*yuv.z;
        float g = yuv.x - 0.1873*yuv.y - 0.4681*yuv.z;
        float b = yuv.x + 1.8556*yuv.y;
        return clamp(float3(r, g, b), 0.0, 1.0);
    }
    float luma(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }


    float2 pxSz() {
        return 1.0 / layer;
    }
    float4 samp(float2 uv) {
        return amzTexture(0, clamp(uv, 0.0, 1.0));
    }



    float3 box3(float2 uv, float2 r) {
        float3 c = float3(0.0);
        c += samp(uv + float2(-r.x,-r.y)).rgb;
        c += samp(uv + float2( 0.0,-r.y)).rgb;
        c += samp(uv + float2( r.x,-r.y)).rgb;
        c += samp(uv + float2(-r.x, 0.0)).rgb;
        c += samp(uv + float2( 0.0, 0.0)).rgb;
        c += samp(uv + float2( r.x, 0.0)).rgb;
        c += samp(uv + float2(-r.x, r.y)).rgb;
        c += samp(uv + float2( 0.0, r.y)).rgb;
        c += samp(uv + float2( r.x, r.y)).rgb;
        return c / 9.0;
    }


    float3 cross5(float2 uv, float2 r) {
        float3 c = samp(uv).rgb * 0.4;
        c += samp(uv + float2( r.x, 0.0)).rgb * 0.15;
        c += samp(uv + float2(-r.x, 0.0)).rgb * 0.15;
        c += samp(uv + float2( 0.0, r.y)).rgb * 0.15;
        c += samp(uv + float2( 0.0,-r.y)).rgb * 0.15;
        return c;
    }


    float3 gauss3(float2 uv, float2 r) {
        float w0=0.44198, w1=0.27901;
        float3 c = float3(0.0);
        c += samp(uv+float2(-r.x,-r.y)).rgb * w1*w1;
        c += samp(uv+float2( 0.0,-r.y)).rgb * w0*w1;
        c += samp(uv+float2( r.x,-r.y)).rgb * w1*w1;
        c += samp(uv+float2(-r.x, 0.0)).rgb * w1*w0;
        c += samp(uv+float2( 0.0, 0.0)).rgb * w0*w0;
        c += samp(uv+float2( r.x, 0.0)).rgb * w1*w0;
        c += samp(uv+float2(-r.x, r.y)).rgb * w1*w1;
        c += samp(uv+float2( 0.0, r.y)).rgb * w0*w1;
        c += samp(uv+float2( r.x, r.y)).rgb * w1*w1;
        return c;
    }


    float hash21(float2 p) {
        p = mod(p, float2(289.0));
        p = fract(p * float2(0.1031, 0.1030));
        p += dot(p, p.yx + float2(33.33));
        return fract((p.x + p.y) * p.x);
    }

    float bayer(float2 uv) {
        float2 amzLocal_pos = mod(floor(uv * layer), 4.0);
        float x = amzLocal_pos.x, y = amzLocal_pos.y;

        float b00=0.0,  b10=0.5,  b20=0.125, b30=0.625;
        float b01=0.75, b11=0.25, b21=0.875, b31=0.375;
        float b02=0.1875, b12=0.6875, b22=0.0625, b32=0.5625;
        float b03=0.9375, b13=0.4375, b23=0.8125, b33=0.3125;
        float val = 0.0;
        if      (y < 0.5) {
            if      (x < 0.5) val=b00;
            else if (x < 1.5) val=b10;
            else if (x < 2.5) val=b20;
            else               val=b30;
        } else if (y < 1.5) {
            if      (x < 0.5) val=b01;
            else if (x < 1.5) val=b11;
            else if (x < 2.5) val=b21;
            else               val=b31;
        } else if (y < 2.5) {
            if      (x < 0.5) val=b02;
            else if (x < 1.5) val=b12;
            else if (x < 2.5) val=b22;
            else               val=b32;
        } else {
            if      (x < 0.5) val=b03;
            else if (x < 1.5) val=b13;
            else if (x < 2.5) val=b23;
            else               val=b33;
        }
        return val - 0.5; 
    }







    float3 applyClarity(float3 col, float2 uv) {
        float2 r   = float2(amzp_clarityRadius);

        float3 lp  = gauss3(uv, r);

        float3 hp  = col - lp;

        float lumV = luma(col);

        float mid  = amzp_clarityMid;
        float bell = 1.0 - abs(lumV - mid) / max(mid, 1.0 - mid);
        bell = clamp(bell, 0.0, 1.0);
        bell = bell * bell; 

        return clamp(col + hp * amzp_clarityAmt * bell, 0.0, 1.0);
    }











    float3 applyDeband(float3 col, float2 uv) {
        float2 r   = float2(amzp_debandRange);
        float2 px  = pxSz();


        float3 n0 = samp(uv + float2( r.x,  0.0)).rgb;
        float3 n1 = samp(uv + float2(-r.x,  0.0)).rgb;
        float3 n2 = samp(uv + float2( 0.0,  r.y)).rgb;
        float3 n3 = samp(uv + float2( 0.0, -r.y)).rgb;
        float3 n4 = samp(uv + float2( r.x,  r.y)).rgb;
        float3 n5 = samp(uv + float2(-r.x,  r.y)).rgb;
        float3 n6 = samp(uv + float2( r.x, -r.y)).rgb;
        float3 n7 = samp(uv + float2(-r.x, -r.y)).rgb;
        float3 avg = (n0+n1+n2+n3+n4+n5+n6+n7) * 0.125;


        float diff = length(col - avg);


        float edgeMask = 1.0;
        if ((amzp_debandEdgeSafe>0.5)) {

            float gx = length(n0 - n1);
            float gy = length(n2 - n3);
            float grad = length(float2(gx, gy));
            edgeMask = 1.0 - smoothstep(amzp_debandThresh, amzp_debandThresh*3.0, grad);
        }


        float bandMask = step(diff, amzp_debandThresh) * edgeMask;


        float dit = bayer(uv) * amzp_debandDither * amzp_debandThresh * 0.5;
        float3 dithered = clamp(avg + float3(dit), 0.0, 1.0);

        return mix(col, dithered, bandMask);
    }










    float3 applyDetailRecovery(float3 col, float2 uv) {
        float2 r    = float2(amzp_detailRadius);
        float3 blr  = cross5(uv, r);


        float3 logI  = log(col  + float3(0.001));
        float3 logB  = log(blr  + float3(0.001));
        float3 retinex = logI - logB; 


        float lumV   = luma(col);
        float shadMask = (1.0 - smoothstep(0.0, 0.5, lumV)) * amzp_detailShadow;

        float highMask = smoothstep(0.5, 1.0, lumV) * amzp_detailHighlight;


        float zoneMask = max(shadMask, highMask);
        float3 boosted = col + retinex * amzp_detailAmt * zoneMask;

        return clamp(boosted, 0.0, 1.0);
    }










    float3 applyCAFix(float3 col, float2 uv) {
        float2 center = float2(0.5);
        float2 dir    = float2(0.0);

        if (int(amzp_caMode) == 0) {

            dir = normalize(uv - center + float2(0.0001));
        } else if (int(amzp_caMode) == 1) {
            dir = float2(1.0, 0.0);
        } else {
            dir = float2(0.0, 1.0);
        }

        float r = amzp_caRadius;


        float rChan = samp(uv + dir * r).r;
        float gChan = col.g;
        float bChan = samp(uv - dir * r).b;

        float3 caFixed = float3(rChan, gChan, bChan);
        return mix(col, caFixed, amzp_caStrength);
    }













    float3 applyBilateral(float3 col, float2 uv) {
        float2  sigS  = float2(amzp_denoiseSpatial);
        float sigC  = amzp_denoiseColor;
        float sigC2 = sigC * sigC * 2.0;

        float3  sum   = float3(0.0);
        float wsum  = 0.0;


        for (int dy = -2; dy <= 2; dy++) {
            for (int dx = -2; dx <= 2; dx++) {
                float2  off  = float2(float(dx), float(dy)) * sigS;
                float3  nbr  = samp(uv + off).rgb;

                float dist2 = float(dx*dx + dy*dy);
                float wSp   = exp(-dist2 / (2.0 * 4.0)); 

                float cdiff = length(nbr - col);
                float wRng  = exp(-(cdiff*cdiff) / sigC2);
                float w     = wSp * wRng;
                sum  += nbr * w;
                wsum += w;
            }
        }
        float3 bilateral = sum / max(wsum, 0.0001);


        if (int(amzp_denoiseMode) == 0) {
            return mix(col, bilateral, amzp_denoiseStrength);
        } else if (int(amzp_denoiseMode) == 1) {

            float3 colYUV = rgb2yuv(col);
            float3 bilYUV = rgb2yuv(bilateral);
            colYUV.x = mix(colYUV.x, bilYUV.x, amzp_denoiseStrength);
            return yuv2rgb(colYUV);
        } else {

            float3 colYUV = rgb2yuv(col);
            float3 bilYUV = rgb2yuv(bilateral);
            colYUV.y = mix(colYUV.y, bilYUV.y, amzp_denoiseStrength);
            colYUV.z = mix(colYUV.z, bilYUV.z, amzp_denoiseStrength);
            return yuv2rgb(colYUV);
        }
    }












    float3 applyHDR(float3 col, float2 uv) {
        float2 r    = float2(amzp_hdrLocalRadius);
        float3 lAvg = cross5(uv, r);
        float lAvgLum = max(luma(lAvg), 0.001);
        float colLum  = luma(col);


        float ratio = colLum / lAvgLum;




        float toned = log(ratio + 1.0) / log(2.0 + 1.0);


        float shadowZone = (1.0 - smoothstep(0.0, 0.4, lAvgLum)) * amzp_hdrShadow;

        float highZone = smoothstep(0.6, 1.0, lAvgLum) * amzp_hdrHighlight;
        float zone = max(shadowZone, highZone);

        float newLum = mix(colLum, toned * lAvgLum, amzp_hdrAmt * zone);

        float3 result;
        if ((amzp_hdrColorSafe>0.5)) {

            float scale = newLum / max(colLum, 0.001);
            result = clamp(col * scale, 0.0, 1.0);
        } else {
            result = clamp(col * (newLum / max(colLum, 0.001)), 0.0, 1.0);
        }
        return result;
    }















    float3 applyTextureBoost(float3 col, float2 uv) {
        float2 r   = float2(amzp_texBoostScale);
        float3 lp  = box3(uv, r);

        float3 dev = col - lp;

        float varSum = 0.0;
        varSum += dot(samp(uv+float2( r.x, 0.0)).rgb - lp, samp(uv+float2( r.x, 0.0)).rgb - lp);
        varSum += dot(samp(uv+float2(-r.x, 0.0)).rgb - lp, samp(uv+float2(-r.x, 0.0)).rgb - lp);
        varSum += dot(samp(uv+float2( 0.0, r.y)).rgb - lp, samp(uv+float2( 0.0, r.y)).rgb - lp);
        varSum += dot(samp(uv+float2( 0.0,-r.y)).rgb - lp, samp(uv+float2( 0.0,-r.y)).rgb - lp);
        float variance = varSum * 0.25;


        float edgeSup = 1.0 - smoothstep(0.0, amzp_texBoostEdgeSup * 0.1, variance);


        float3 boosted = lp + dev * (1.0 + amzp_texBoostAmt * edgeSup);
        return clamp(boosted, 0.0, 1.0);
    }


    void amzRender() {
        float2 uv  = amzScreenNorm();
        float4 src = samp(uv);
        float3 col = src.rgb;





        if ((amzp_denoiseOn>0.5)) {
            col = applyBilateral(col, uv);
        }


        if ((amzp_debandOn>0.5)) {
            col = applyDeband(col, uv);
        }


        if ((amzp_caOn>0.5)) {
            col = applyCAFix(col, uv);
        }


        if ((amzp_hdrOn>0.5)) {
            col = applyHDR(col, uv);
        }


        if ((amzp_clarityOn>0.5)) {
            col = applyClarity(col, uv);
        }


        if ((amzp_detailOn>0.5)) {
            col = applyDetailRecovery(col, uv);
        }


        if ((amzp_texBoostOn>0.5)) {
            col = applyTextureBoost(col, uv);
        }


        if (amzp_outputGamma != 1.0) {
            col = pow(clamp(col, 0.0, 1.0), float3(1.0 / amzp_outputGamma));
        }

        amzOutput = float4(clamp(col, 0.0, 1.0), src.a) * amzp_alpha;
    }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

